<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $logs = amia_premium_agum_logs( 10 ); ?>
<div class="amia-section-head"><h2>Recent Activity</h2><?php if ( current_user_can( 'manage_options' ) ) : ?><button class="amia-btn amia-clear-activity" type="button">Clear Recent Activity</button><?php endif; ?></div><div class="amia-activity-list"><?php foreach ( $logs as $log ) : ?><div class="amia-card"><strong><?php echo esc_html( $log->action ); ?></strong><p class="amia-muted"><?php echo esc_html( $log->message ); ?></p><time><?php echo esc_html( $log->created_at ); ?></time></div><?php endforeach; ?><?php if ( ! $logs ) : ?><div class="amia-card">No recent activity.</div><?php endif; ?></div>
